//! **FP8 (E4M3) elementwise kernels**: the programs the virtual accelerator
//! runs.
//!
//! One operand, one result, each an E4M3 byte: OCP 8-bit floating point
//! (`torch.float8_e4m3fn`), a sign, four exponent bits biased by 7 and three
//! mantissa bits, with no infinities, one NaN (`S.1111.111`), a largest
//! magnitude of 448 and subnormals in steps of 2⁻⁹.
//!
//! Each kernel is a table lookup. The tables are generated by
//! `tools/fp8_tables.py`, whose documentation defines every entry: the exact
//! real result rounded to nearest, ties to even; saturating at ±448, since
//! there is no infinity; the canonical NaN `0x7f` for a NaN operand and for a
//! result outside the reals. The generator derives them in exact and
//! 120-digit arithmetic and proves each rounding decision by its margin, so
//! a result does not depend on any machine's math library. That is the point
//! of defining a device by a table: a driver writer needs one answer.
//!
//! A program is named the way every kernel of the CPU backend is: the
//! registered-kernel artifact format, with the kernel's id in the target
//! identity ([`Kernel::identity`]). A submission binds the operand buffer to
//! slot 0, read, and the result buffer to slot 1, written; the result's
//! length is the element count.

use kore_svc_accel_spmd::{Kernel, TileCtx};

mod tables;

/// One of the device's functions.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    Sin,
    Cos,
    Tan,
    Exp,
    Log,
    Sqrt,
}

impl Op {
    /// Every function, in kernel-id order.
    pub const ALL: [Self; 6] = [
        Self::Sin,
        Self::Cos,
        Self::Tan,
        Self::Exp,
        Self::Log,
        Self::Sqrt,
    ];

    /// The kernel id a program names this function by.
    ///
    /// The ids are this device's own: a registry is per backend instance,
    /// so they share nothing with another CPU row's kernels. They start at
    /// `0x0100` so that a driver which confuses the two registries names a
    /// kernel neither has.
    pub const fn kernel_id(self) -> u32 {
        0x0100 + self as u32
    }

    /// The table that defines this function: its result for each byte.
    pub const fn table(self) -> &'static [u8; 256] {
        match self {
            Self::Sin => &tables::SIN,
            Self::Cos => &tables::COS,
            Self::Tan => &tables::TAN,
            Self::Exp => &tables::EXP,
            Self::Log => &tables::LOG,
            Self::Sqrt => &tables::SQRT,
        }
    }

    /// The name a status line prints.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Sin => "sin.e4m3",
            Self::Cos => "cos.e4m3",
            Self::Tan => "tan.e4m3",
            Self::Exp => "exp.e4m3",
            Self::Log => "log.e4m3",
            Self::Sqrt => "sqrt.e4m3",
        }
    }

    /// This function of one value.
    #[inline]
    pub const fn apply(self, operand: u8) -> u8 {
        self.table()[operand as usize]
    }
}

/// Run one span: `out[i] = table[operand[first + i]]`.
///
/// A byte indexes a 256-byte table, which is the whole computation and has
/// no wider form: the table fits four cache lines and the span is already
/// one worker's share of the grid.
#[inline]
fn map(ctx: TileCtx<'_>, table: &[u8; 256]) {
    let first = ctx.tiles.start as usize;
    let operands = &ctx.inputs[0][first..first + ctx.out.len()];
    for (result, operand) in ctx.out.iter_mut().zip(operands) {
        *result = table[usize::from(*operand)];
    }
}

macro_rules! kernels {
    ($($op:ident => $run:ident),+ $(,)?) => {
        $(fn $run(ctx: TileCtx<'_>) {
            map(ctx, Op::$op.table());
        })+

        /// The device's kernel registry: what [`SpmdBackend::new`] is given.
        ///
        /// [`SpmdBackend::new`]: kore_svc_accel_spmd::SpmdBackend::new
        pub static KERNELS: &[Kernel] = &[
            $(Kernel {
                id: Op::$op.kernel_id(),
                name: Op::$op.name(),
                inputs: 1,
                elem_bytes: 1,
                // A lookup has no lanes: one element a step.
                lanes: 1,
                run: $run,
            }),+
        ];
    };
}

kernels! {
    Sin => sin,
    Cos => cos,
    Tan => tan,
    Exp => exp,
    Log => log,
    Sqrt => sqrt,
}

